<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { Edit2, Plus, Search, ToggleLeft, ToggleRight } from 'lucide-vue-next';
import NxrSlidePanel from '../../components/NxrSlidePanel.vue';
import { usePermissions } from '../../composables/usePermissions';
import { useTreasurySettingsStore } from '../../stores/treasurySettings';
import type { TreasuryCashRegister, TreasuryCashRegisterFormData, TreasuryCounterparty, TreasuryCounterpartyFormData, TreasuryPaymentTerm, TreasuryPaymentTermFormData } from '../../types/treasury';

type Tab = 'counterparties' | 'paymentTerms' | 'cashRegisters';
const labels = { counterparties: 'Contrapartes', paymentTerms: 'Condiciones de pago', cashRegisters: 'Cajas' };
const { canDo, isReadOnly } = usePermissions();
const store = useTreasurySettingsStore();
const activeTab = ref<Tab>('counterparties');
const q = ref('');
const status = ref<'active' | 'inactive' | 'all'>('active');
const showForm = ref(false);
const editing = ref<any>(null);
const saving = ref(false);
const error = ref('');
const counterparty = ref<TreasuryCounterpartyFormData>({ counterparty_type: 'customer', name_snapshot: '', document_type: 'RUT', document_number: '', phone: '', email: '' });
const paymentTerm = ref<TreasuryPaymentTermFormData>({ code: '', name: '', term_type: 'cash', days_due: 0, installments_count: 1, grace_days: 0 });
const cashRegister = ref<TreasuryCashRegisterFormData>({ code: '', name: '', location: '' });
const catalog = computed(() => store[activeTab.value]);
const canEdit = computed(() => !isReadOnly.value && (canDo('treasury_settings', 'can_create') || canDo('treasury_settings', 'can_edit')));

async function load() { await catalog.value.load({ q: q.value || undefined, status: status.value }); }
onMounted(load);
watch([activeTab, q, status], load);
function reset() {
  counterparty.value = { counterparty_type: 'customer', name_snapshot: '', document_type: 'RUT', document_number: '', phone: '', email: '' };
  paymentTerm.value = { code: '', name: '', term_type: 'cash', days_due: 0, installments_count: 1, grace_days: 0 };
  cashRegister.value = { code: '', name: '', location: '' };
}
function create() { reset(); editing.value = null; error.value = ''; showForm.value = true; }
function edit(item: TreasuryCounterparty | TreasuryPaymentTerm | TreasuryCashRegister) { editing.value = item; error.value = ''; if (activeTab.value === 'counterparties') { const value = item as TreasuryCounterparty; counterparty.value = { counterparty_type: value.counterparty_type, name_snapshot: value.name_snapshot, document_type: value.document_type || '', document_number: value.document_number || '', phone: value.phone || '', email: value.email || '' }; } else if (activeTab.value === 'paymentTerms') { const value = item as TreasuryPaymentTerm; paymentTerm.value = { code: value.code, name: value.name, term_type: value.term_type, days_due: Number(value.days_due), installments_count: Number(value.installments_count), grace_days: Number(value.grace_days) }; } else { const value = item as TreasuryCashRegister; cashRegister.value = { code: value.code, name: value.name, location: value.location || '' }; } showForm.value = true; }
async function save() { saving.value = true; error.value = ''; try { if (activeTab.value === 'counterparties') { if (!counterparty.value.name_snapshot.trim() || !counterparty.value.document_number?.trim()) throw new Error('El nombre y el documento son requeridos'); if (editing.value) await store.counterparties.update(editing.value.id, counterparty.value); else await store.counterparties.create(counterparty.value); } else if (activeTab.value === 'paymentTerms') { if (!paymentTerm.value.code.trim() || !paymentTerm.value.name.trim()) throw new Error('El c\u00f3digo y el nombre son requeridos'); if (editing.value) await store.paymentTerms.update(editing.value.id, paymentTerm.value); else await store.paymentTerms.create(paymentTerm.value); } else { if (!cashRegister.value.code.trim() || !cashRegister.value.name.trim()) throw new Error('El c\u00f3digo y el nombre son requeridos'); if (editing.value) await store.cashRegisters.update(editing.value.id, cashRegister.value); else await store.cashRegisters.create(cashRegister.value); } showForm.value = false; await load(); } catch (cause: any) { error.value = cause?.response?.data?.error || cause?.message || 'No fue posible guardar'; } finally { saving.value = false; } }
async function toggle(item: any) { try { await catalog.value.toggleStatus(item.id, item.status === 'active' ? 'inactive' : 'active'); } catch { /* The store exposes the error in catalog.error. */ } }
function title(item: any) { return activeTab.value === 'counterparties' ? item.name_snapshot : item.name; }
function detail(item: any) { if (activeTab.value === 'counterparties') return item.document_number || 'Sin documento'; if (activeTab.value === 'paymentTerms') return item.term_type + ' - ' + item.days_due + ' d\u00edas'; return item.location || 'Sin ubicaci\u00f3n'; }
</script>

<template><div class="flex flex-col gap-5 p-3 sm:p-6"><div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h1 class="text-xl font-semibold text-white">Configuraci&#243;n de Tesorer&#237;a</h1><p class="text-xs text-white/40">Contrapartes, condiciones de pago y cajas.</p></div><button v-if="canEdit" class="nxr-btn nxr-btn-primary" @click="create"><Plus :size="15" /> Nuevo</button></div><div class="flex gap-2 overflow-x-auto" role="tablist"><button v-for="(_, key) in labels" :key="key" :class="['whitespace-nowrap rounded-xl px-3 py-2 text-sm', activeTab === key ? 'bg-white/15 text-white' : 'bg-white/5 text-white/50']" @click="activeTab = key as Tab">{{ labels[key as Tab] }}</button></div><div class="flex flex-col gap-3 sm:flex-row"><div class="relative flex-1"><Search :size="14" class="absolute left-3 top-1/2 -translate-y-1/2 text-white/30" /><input v-model="q" class="w-full rounded-xl border border-white/10 bg-white/5 py-2 pl-9 pr-4 text-sm text-white" placeholder="Buscar..." /></div><select v-model="status" class="rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-sm text-white"><option value="active">Activos</option><option value="inactive">Inactivos</option><option value="all">Todos</option></select></div><p v-if="catalog.error" class="text-sm text-red-400">{{ catalog.error }}</p><div class="grid grid-cols-1 gap-3 md:grid-cols-2"><article v-for="item in catalog.items" :key="item.id" class="flex items-center justify-between rounded-xl border border-white/10 p-4"><div><p class="text-sm font-semibold text-white">{{ title(item) }}</p><p class="text-xs text-white/40">{{ detail(item) }}</p></div><div class="flex gap-2"><button v-if="canEdit" @click="edit(item)"><Edit2 :size="16" /></button><button v-if="canEdit" @click="toggle(item)"><ToggleRight v-if="item.status === 'active'" :size="19" /><ToggleLeft v-else :size="19" /></button></div></article></div><NxrSlidePanel :open="showForm" :title="editing ? 'Editar registro' : 'Nuevo registro'" size="md" @close="showForm = false"><div v-if="activeTab === 'counterparties'" class="grid grid-cols-1 gap-3 sm:grid-cols-2"><input v-model="counterparty.name_snapshot" placeholder="Nombre" class="sm:col-span-2 rounded-xl border border-white/10 bg-white/5 p-2 text-white" /><select v-model="counterparty.counterparty_type" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white"><option value="customer">Cliente</option><option value="supplier">Proveedor</option><option value="both">Ambos</option></select><input v-model="counterparty.document_number" placeholder="Documento" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white" /><input v-model="counterparty.phone" placeholder="Tel&#233;fono" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white" /><input v-model="counterparty.email" placeholder="Email" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white" /></div><div v-else-if="activeTab === 'paymentTerms'" class="grid grid-cols-1 gap-3 sm:grid-cols-2"><input v-model="paymentTerm.code" placeholder="C&#243;digo" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white" /><input v-model="paymentTerm.name" placeholder="Nombre" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white" /><select v-model="paymentTerm.term_type" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white"><option value="cash">Contado</option><option value="credit">Cr&#233;dito</option><option value="installments">Cuotas</option></select><input v-model.number="paymentTerm.days_due" type="number" min="0" placeholder="D&#237;as" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white" /><input v-model.number="paymentTerm.installments_count" type="number" min="1" placeholder="Cuotas" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white" /><input v-model.number="paymentTerm.grace_days" type="number" min="0" placeholder="D&#237;as de gracia" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white" /></div><div v-else class="grid grid-cols-1 gap-3 sm:grid-cols-2"><input v-model="cashRegister.code" placeholder="C&#243;digo" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white" /><input v-model="cashRegister.name" placeholder="Nombre" class="rounded-xl border border-white/10 bg-white/5 p-2 text-white" /><input v-model="cashRegister.location" placeholder="Ubicaci&#243;n" class="sm:col-span-2 rounded-xl border border-white/10 bg-white/5 p-2 text-white" /></div><p v-if="error" class="text-xs text-red-400">{{ error }}</p><template #footer><button class="nxr-btn nxr-btn-primary" :disabled="saving" @click="save">Guardar</button></template></NxrSlidePanel></div></template>
